  if(k==='pts'){const o=[],st=v||4;for(let i=0;i<NP;i+=st)o.push([Math.round(pts[i].x),Math.round(pts[i].y),Math.round(pts[i].z)]);return {L:Math.round(L),NP:NP,pas:st,p:o};} // (banc) la route, un point sur `v`
