    const p=P[i],pa=P[Math.max(i-1,0)],pb=P[Math.min(i+1,ARC_NS-1)];  // (2026-10-08) la direction du chemin ignore un TROU (la nitro reprise plus loin, la tête qui file pendant l'extinction)
