  if(F.shT>0){F.shT-=dt;tgt*=.66;if(F.shT<=0&&F.shift>0){flmPops(.5+.7*F.shift,F.shift>.8&&Math.random()<.6?1:0);F.shift=0;}} // la coupure finie : le carburant non brûlé SAUTE
  if(vol)tgt=.86+.12*Math.random();
