            yB=Math.max(U.lin([[-2.07,.84],[-1.98,.88],[-.74,.92],[.62,.72],[2.07,.44]],z),yb+.10),c=yC(z);
      const p4=cab(z)?[.80,yB+.02]:[xw-.08,yB+.005];
