      P.prism('k',[[-.25,.62],[-.85,.66],[-.85,.78],[-.25,.645]],.02,sd*1.001); // LA NACA, en biais — (19/10) en TRAPÈZE, pointue devant (une plaque rectangulaire)
      P.box('k',.98,.04,.30,sd*.49,1.16+.035,-1.88,0,0,sd*.07);                 // l'aileron en V…
