    P.put('r',new THREE.SphereGeometry(1,12,6),0,2.13,-.20,0,0,0,.28,.045,1.36); // LA PLANCHE DE SURF
    P.box('s',.03,.006,2.1,0,2.176,-.20);                                     // son liteau
