     for(const x of [-.072,.072]){Q.cyl('c',.063,.016,16,x,-HB-.016,.08);Q.cyl('W',.052,.01,16,x,-HB-.021,.08);Q.cyl('c',.014,.006,8,x,-HB-.028,.08);} // les deux phares ronds : cerclage, glace, moyeu
