    if(j<=1)return 'n';
    if(j===5&&cab(z)&&z>-1.25)return (z>-.35&&z<-.29)?'n':'g';                // vitre de porte, la GRANDE custode
    if(j===5&&cab(z)&&z<=-1.25)return 'p';
