  P.box('n',.40,.13,.02,0,.62,-2.215);P.box('w',.36,.10,.012,0,.62,-2.228);P.box('W',.10,.014,.01,0,.69,-2.222); // la plaque, sa lampe
  P.prism('p',[[-2.16,.54],[-2.245,.53],[-2.26,.46],[-2.25,.39],[-2.20,.37],[-2.16,.37]],1.56,0);                 // le bouclier…
