  P.box('n',1.36,.12,.05,0,.33,-2.245);for(const x of [0,-.13,.13,-.52,.52,-.64,.64])P.box('K',.016,.11,.07,x,.33,-2.26); // la jupe, ses ailettes
  P.cyl('c',.055,.02,10,-.60,T(-1.95)+.01,-1.95,'y');                          // le bouchon de réservoir
