  tige('c',[-.58,RR9,ZR],[.58,RR9,ZR],.04,10);P.lathe('c',[[0,-.12],[.12,-.08],[.13,0],[.12,.08],[0,.12]],12,0,RR9,ZR,'z');P.box('k',.12,.08,.10,0,RR9,ZR+.12);   // le pont « quick-change »
