  const ov=(cx,cy,rx,ry,a,n)=>{const o=[];for(let i=0;i<(n||20);i++){const t=i/(n||20)*Math.PI*2,x=Math.cos(t)*rx,y=Math.sin(t)*ry;o.push([cx+x*Math.cos(a)-y*Math.sin(a),cy+x*Math.sin(a)+y*Math.cos(a)]);}return o;};
