        for(let i=0;i<6;i++){x.fillStyle='rgba(40,20,5,'+(.12+Math.random()*.15)+')';x.beginPath();x.arc(.05*w+Math.random()*.2*w,.2*h+Math.random()*.6*h,3+Math.random()*7,0,Math.PI*2);x.fill();} // l'huile de ricin
