    for(const fz of [-.24,.24]){ailTige(piv,fil,.006,A.set(sd*S*.5,-.02,fz),B.set(sd*S*.9,.38,fz));ailTige(piv,fil,.006,A.set(sd*S*.5,.38,fz),B.set(sd*S*.9,-.02,fz));} // les haubans
