          ins=function(p,k){return [p.x*k,Rk+(p.y-Rk)*k];},chemin=function(k){x.beginPath();pts.forEach(function(p,i){const q=ins(p,k),c=X(q[0],q[1]);if(i)x.lineTo(c[0],c[1]);else x.moveTo(c[0],c[1]);});x.closePath();};
